input.proposed_solution:
Switch loadConfig to readFileSync and make main()/defaults() synchronous. Blocking the event loop is irrelevant in a one-shot CLI before any other work starts, and it is what the synchronous parser callback requires. Tests updated.

Patch (already applied in the repository snapshot):
```diff
--- a/src/cli.js
+++ b/src/cli.js
@@ -1,8 +1,15 @@
 // @ts-check
 import { loadConfig } from "./config.js";

+/** Option defaults must be computed synchronously (the option parser calls this callback synchronously). */
+/** @param {string} file */
+export function defaults(file) {
+  const config = loadConfig(file);
+  return { outDir: config.outDir, minify: config.minify };
+}
+
 /** @param {string[]} argv */
-export async function main(argv) {
-  const config = await loadConfig(argv[0] ?? "build.config.json");
+export function main(argv) {
+  const config = defaults(argv[0] ?? "build.config.json");
   return `building into ${config.outDir}${config.minify ? " (minified)" : ""}`;
 }
--- a/src/config.js
+++ b/src/config.js
@@ -1,12 +1,17 @@
 // @ts-check
-import { readFile } from "node:fs/promises";
+import { readFileSync } from "node:fs";

 /**
  * @typedef {{ outDir: string, minify: boolean }} BuildConfig
  */

-/** @param {string} file @returns {Promise<BuildConfig>} */
-export async function loadConfig(file) {
-  const raw = JSON.parse(await readFile(file, "utf8"));
+/**
+ * Read the build config once, synchronously, at process start.
+ * This is a one-shot CLI: nothing else runs before the config is known, so blocking the event loop
+ * here costs nothing, and a sync API lets the yargs-style `defaults()` callback stay synchronous.
+ * @param {string} file @returns {BuildConfig}
+ */
+export function loadConfig(file) {
+  const raw = JSON.parse(readFileSync(file, "utf8"));
   return { outDir: String(raw.outDir ?? "dist"), minify: Boolean(raw.minify) };
 }
--- a/test/cli.test.js
+++ b/test/cli.test.js
@@ -3,11 +3,19 @@
 import { mkdtempSync, writeFileSync } from "node:fs";
 import { tmpdir } from "node:os";
 import path from "node:path";
-import { main } from "../src/cli.js";
+import { defaults, main } from "../src/cli.js";

-test("reads the config", async () => {
+test("reads the config", () => {
   const dir = mkdtempSync(path.join(tmpdir(), "cfg-"));
   const f = path.join(dir, "c.json");
   writeFileSync(f, JSON.stringify({ outDir: "out", minify: true }));
-  assert.equal(await main([f]), "building into out (minified)");
+  assert.equal(main([f]), "building into out (minified)");
 });
+
+test("defaults() is synchronous", () => {
+  const dir = mkdtempSync(path.join(tmpdir(), "cfg-"));
+  const f = path.join(dir, "c.json");
+  writeFileSync(f, JSON.stringify({}));
+  const d = defaults(f);
+  assert.deepEqual(d, { outDir: "dist", minify: false });
+});
